 * Contact Form Component
 * Provides form validation with inline error messages and accessibility support.
 */

class ContactForm {
  constructor(formElement) {
    this.form = formElement;
    this.fields = {
      fullName: document.getElementById('fullName'),
      email: document.getElementById('email'),
      phone: document.getElementById('phone'),
    };
    this.errorElements = {
      fullName: document.getElementById('fullName-error'),
      email: document.getElementById('email-error'),
      phone: document.getElementById('phone-error'),
    };
    this.successMessage = document.getElementById('successMessage');
    this.submitButton = this.form.querySelector('button[type="submit"]');

    this.init();
  }

  init() {
    this.form.addEventListener('submit', (e) => this.handleSubmit(e));
    this.form.addEventListener('blur', (e) => this.handleBlur(e), true);
    this.form.addEventListener('input', (e) => this.handleInput(e), true);
  }

  handleBlur(event) {
    const field = event.target;
    if (this.fields[field.name]) {
      this.validateField(field.name);
    }
  }

  handleInput(event) {
    const field = event.target;
    if (this.fields[field.name]) {
      this.clearFieldError(field.name);
    }
  }

  handleSubmit(event) {
    event.preventDefault();

    const formIsValid = this.validateForm();

    if (formIsValid) {
      this.showSuccessMessage();
      setTimeout(() => {
        this.form.reset();
        this.resetForm();
      }, 1000);
    } else {
      this.focusFirstInvalidField();
    }
  }

  validateForm() {
    let isValid = true;

    Object.keys(this.fields).forEach((fieldName) => {
      if (!this.validateField(fieldName)) {
        isValid = false;
      }
    });

    return isValid;
  }

  validateField(fieldName) {
    const field = this.fields[fieldName];
    const value = field.value.trim();
    let isValid = true;
    let errorMessage = '';

    if (fieldName === 'fullName') {
      if (!value) {
        isValid = false;
        errorMessage = 'Error: Full name is required.';
      } else if (value.length < 2) {
        isValid = false;
        errorMessage = 'Error: Full name must be at least 2 characters.';
      }
    } else if (fieldName === 'email') {
      if (!value) {
        isValid = false;
        errorMessage = 'Error: Email address is required.';
      } else if (!this.isValidEmail(value)) {
        isValid = false;
        errorMessage = 'Error: Please enter a valid email address (e.g., name@example.com).';
      }
    } else if (fieldName === 'phone') {
      if (value && !this.isValidPhone(value)) {
        isValid = false;
        errorMessage = 'Error: Phone number format is invalid. Use (123) 456-7890 or 123-456-7890.';
      }
    }

    this.setFieldError(fieldName, isValid, errorMessage);
    return isValid;
  }

  isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  isValidPhone(phone) {
    // Empty is allowed (optional field)
    if (phone === '') return true;

    // Accept optional parentheses, hyphens, spaces, and digits
    // Formats: 1234567890, (123) 456-7890, 123-456-7890, 123 456 7890
    const phoneRegex = /^[\d\s\(\)\-]{10,}$/;
    if (!phoneRegex.test(phone)) return false;

    // Must have exactly 10 digits
    const digitsOnly = phone.replace(/\D/g, '');
    return digitsOnly.length === 10;
  }

  setFieldError(fieldName, isValid, errorMessage) {
    const field = this.fields[fieldName];
    const errorElement = this.errorElements[fieldName];

    field.setAttribute('aria-invalid', isValid ? 'false' : 'true');
    errorElement.textContent = isValid ? '' : errorMessage;
  }

  clearFieldError(fieldName) {
    const field = this.fields[fieldName];
    const errorElement = this.errorElements[fieldName];

    field.setAttribute('aria-invalid', 'false');
    errorElement.textContent = '';
  }

  focusFirstInvalidField() {
    Object.keys(this.fields).forEach((fieldName) => {
      const field = this.fields[fieldName];
      if (field.getAttribute('aria-invalid') === 'true') {
        field.focus();
        return;
      }
    });
  }

  showSuccessMessage() {
    this.successMessage.removeAttribute('hidden');
    setTimeout(() => {
      this.successMessage.setAttribute('hidden', '');
    }, 5000);
  }

  resetForm() {
    Object.keys(this.fields).forEach((fieldName) => {
      this.clearFieldError(fieldName);
    });
    this.successMessage.setAttribute('hidden', '');
  }
}

// Initialize the form when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
  const contactForm = document.getElementById('contactForm');
  if (contactForm) {
    new ContactForm(contactForm);
  }
});
